class Dog:
    def speak(self): return 'woof'
class Cat:
    def speak(self): return 'meow'
for pet in (Dog(), Cat()): print(pet.speak())

class TextSource:
    def read(self): return 'text'
class NumberSource:
    def read(self): return 42
def show(source): print(source.read())
show(TextSource()); show(NumberSource())

class Circle:
    def area(self): return 12
class Square:
    def area(self): return 9
def total_area(shapes): return sum(s.area() for s in shapes)
print(total_area([Circle(), Square()]))

def export(item):
    method = getattr(item, 'to_csv', None)
    if method is None: return 'unsupported'
    return method()
class Note: pass
print(export(Note()))
